import java.nio.file.*;import java.util.*;import java.util.zip.*;
import org.objectweb.asm.*;import org.objectweb.asm.tree.*;
public class VerifyBundle {
 static Map<String,ClassNode> classes=new HashMap<>();
 static ClassNode load(ZipFile z,String p)throws Exception{var n=new ClassNode();new ClassReader(z.getInputStream(z.getEntry(p)).readAllBytes()).accept(n,0);return n;}
 static boolean hasMethod(String owner,String name,String desc){var c=classes.get(owner);if(c==null)return !owner.startsWith("school/magiccodex/");return c.methods.stream().anyMatch(m->m.name.equals(name)&&m.desc.equals(desc))||(c.superName!=null&&hasMethod(c.superName,name,desc));}
 static boolean hasField(String owner,String name,String desc){var c=classes.get(owner);if(c==null)return !owner.startsWith("school/magiccodex/");return c.fields.stream().anyMatch(m->m.name.equals(name)&&m.desc.equals(desc))||(c.superName!=null&&hasField(c.superName,name,desc));}
 static List<String> instructions(MethodNode m,boolean stripHook){var out=new ArrayList<String>();for(var i:m.instructions){if(i.getOpcode()<0)continue;if(stripHook&&i instanceof MethodInsnNode n&&n.owner.endsWith("/NameplateBootstrap")&&n.name.equals("initialize")){if(!out.removeLast().equals("25 0"))throw new AssertionError("hook argument");continue;}if(stripHook&&i instanceof MethodInsnNode n&&n.owner.endsWith("/NameplateClient")&&n.name.equals("initialize"))continue;String s=""+i.getOpcode();if(i instanceof MethodInsnNode n)s+=" "+n.owner+" "+n.name+" "+n.desc;if(i instanceof FieldInsnNode n)s+=" "+n.owner+" "+n.name+" "+n.desc;if(i instanceof VarInsnNode n)s+=" "+n.var;if(i instanceof IntInsnNode n)s+=" "+n.operand;if(i instanceof TypeInsnNode n)s+=" "+n.desc;if(i instanceof LdcInsnNode n)s+=" "+(n.cst instanceof String x?x.replace("ch1-14","ch1-15"):n.cst);if(i instanceof InvokeDynamicInsnNode n)s+=" "+n.name+" "+n.desc+" "+Arrays.toString(n.bsmArgs);if(i instanceof IincInsnNode n)s+=" "+n.var+" "+n.incr;s=s.replaceAll("(lambda\\$[^ ]*)\\$[0-9]+", "$1");s=s.replace("ch1-14","ch1-15");out.add(s);}return out;}
 public static void main(String[] args)throws Exception{
  boolean client=args[2].equals("client");String prefix="school/magiccodex/";var allowed=client?Set.of(prefix+"client/MagicCodexClient.class",prefix+"client/CodexTypography.class",prefix+"client/HudTextureCache.class",prefix+"mixin/TamingNameMixin.class",prefix+"client/CodexTextRasterizer.class","fabric.mod.json"):Set.of(prefix+"paper/MagicCodexBridge.class",prefix+"paper/TitleBridge.class",prefix+"paper/SchoolBridge.class","plugin.yml");
  try(var base=new ZipFile(args[0]);var patched=new ZipFile(args[1])){int changed=0,added=0,methods=0,refs=0;var en=patched.entries();
   while(en.hasMoreElements()){var e=en.nextElement();if(e.getName().startsWith(prefix)&&e.getName().endsWith(".class"))classes.put(e.getName().substring(0,e.getName().length()-6),load(patched,e.getName()));}
   en=base.entries();while(en.hasMoreElements()){var e=en.nextElement();var p=patched.getEntry(e.getName());if(p==null)throw new AssertionError("Removed "+e.getName());if(!Arrays.equals(base.getInputStream(e).readAllBytes(),patched.getInputStream(p).readAllBytes())){changed++;if(!allowed.contains(e.getName())&&!e.getName().contains("/Nameplate"))throw new AssertionError("Unrelated ZIP change "+e.getName());}
    if(allowed.contains(e.getName())&&e.getName().endsWith(".class")){var old=load(base,e.getName());var now=load(patched,e.getName());for(var m:old.methods){var next=now.methods.stream().filter(n->n.desc.equals(m.desc)&&(m.name.startsWith("lambda$")?(n.name.startsWith(m.name.substring(0,m.name.lastIndexOf('$')+1))&&instructions(m,true).equals(instructions(n,true))):n.name.equals(m.name))).findFirst().orElseThrow(()->new AssertionError("Missing preserved method "+old.name+" "+m.name));if(m.name.equals("magiccodex$tamingName")||(old.name.endsWith("/CodexTypography")&&List.of("<init>","beginFrame","clearSprites").contains(m.name)))continue;if(!instructions(m,true).equals(instructions(next,true)))throw new AssertionError("Unrelated method change "+old.name+" "+m.name);methods++;}}
   }
   en=patched.entries();while(en.hasMoreElements()){var e=en.nextElement();if(base.getEntry(e.getName())==null){added++;String p=e.getName();if(!(p.startsWith(prefix+"client/Nameplate")||p.startsWith(prefix+"paper/Nameplate")||p.startsWith(prefix+"protocol/NameplateProtocol")||p.startsWith("assets/magiccodex/textures/nameplates/")||p.equals(prefix+"client/CodexTypography$TitleKey.class")))throw new AssertionError("Unrelated addition "+p);}}
   for(var c:classes.values())if(c.name.contains("Nameplate")||allowed.contains(c.name+".class"))for(var m:c.methods)for(var i:m.instructions){if(i instanceof MethodInsnNode n&&n.owner.startsWith(prefix)){if(!hasMethod(n.owner,n.name,n.desc))throw new AssertionError("Missing method "+n.owner+" "+n.name+n.desc);refs++;}if(i instanceof FieldInsnNode n&&n.owner.startsWith(prefix)){if(!hasField(n.owner,n.name,n.desc))throw new AssertionError("Missing field "+n.owner+" "+n.name+n.desc);refs++;}if(i instanceof InvokeDynamicInsnNode n)for(var arg:n.bsmArgs)if(arg instanceof Handle h&&h.getOwner().startsWith(prefix)){if(!hasMethod(h.getOwner(),h.getName(),h.getDesc()))throw new AssertionError("Missing lambda target "+h);refs++;}}
   System.out.println("PASS "+args[2]+": changed existing entries="+changed+", added="+added+", preserved method bodies="+methods+", resolved package references="+refs+"; all unrelated ZIP entries byte-identical");
  }
 }
}
